<?php
namespace App\Http\Controllers\API\Hub\V1;use App\Domain\ApiHub\ApiIdempotencyService;use App\Domain\ApiHub\Models\TenantApiOperationLink;use App\Domain\Network\Billing\EntitlementService;use App\Domain\Network\Channels\B2C\TenantOperationService;use App\Domain\Shipping\LastMile\DeliveryRequirementService;use App\Domain\Shipping\Local\{LocalGuideService,LocalShipmentService,LocalTrackingService};use Illuminate\Http\Request;
final class ShipmentController extends ApiV1Controller{public function store(Request$r,ApiIdempotencyService$idem,TenantOperationService$operations,LocalShipmentService$shipments,DeliveryRequirementService$proofs){$key=$this->idempotencyKey($r);if(!$key)return$this->error($r,'IDEMPOTENCY_KEY_REQUIRED','Idempotency-Key es obligatorio.',400);$d=$r->validate(['quote_id'=>['required','uuid'],'option_id'=>['required','uuid'],'sender.name'=>['required','string','max:160'],'sender.phone'=>['required','string','max:30'],'sender.address'=>['required','string','max:500'],'sender.postal_code'=>['required','regex:/^[0-9]{5}$/'],'recipient.name'=>['required','string','max:160'],'recipient.phone'=>['required','string','max:30'],'recipient.address'=>['required','string','max:500'],'recipient.postal_code'=>['required','regex:/^[0-9]{5}$/'],'customer_reference'=>['nullable','string','max:160'],'proof_option_uuid'=>['nullable','uuid']]);$tenant=$r->attributes->get('tenant');$client=$r->attributes->get('api_client');if(!app(EntitlementService::class)->has($tenant,'SHIPPING'))return$this->error($r,'SHIPPING_ENTITLEMENT_REQUIRED','El tenant no tiene Shipping activo.',403);$result=$idem->execute($tenant->id,$client->id,'shipments.create',$key,$d,function()use($d,$tenant,$client,$operations,$shipments,$proofs){$link=TenantApiOperationLink::with('operation')->where('uuid',$d['quote_id'])->where('tenant_id',$tenant->id)->where('api_client_id',$client->id)->lockForUpdate()->firstOrFail();if($link->expires_at->isPast())return['status'=>422,'body'=>['error'=>['code'=>'QUOTE_EXPIRED','message'=>'La cotización expiró.']]];$option=$link->quote_snapshot['options'][$d['option_id']]??null;if(!$option)return['status'=>422,'body'=>['error'=>['code'=>'INVALID_QUOTE_OPTION','message'=>'La opción no pertenece a esta cotización.']]];if(strtoupper((string)$option['provider'])!=='ZIGO_LOCAL')return['status'=>503,'body'=>['error'=>['code'=>'PROVIDER_UNAVAILABLE','message'=>'El adaptador de compra no está disponible en API Hub V1.']]];$proof=$proofs->option($tenant,$d['proof_option_uuid']??null);$operation=$link->operation;$meta=$operation->metadata??[];$meta['selected_quote']=['service'=>$option['service_name'],'service_code'=>$option['service_code'],'provider'=>$option['provider'],'price'=>$option['price'],'currency'=>$option['currency']];$operation->update(['channel'=>'api','provider'=>$option['provider'],'service_code'=>$option['service_code'],'external_reference'=>$d['customer_reference']??$link->external_reference,'metadata'=>$meta]);$operations->confirm($tenant,$operation);$shipment=$shipments->create($tenant,$operation->fresh(),['sender'=>$d['sender'],'recipient'=>$d['recipient'],'package'=>$link->quote_snapshot['package'],'reference'=>$d['customer_reference']??null,'pricing'=>['final_price'=>$option['price'],'currency'=>$option['currency']],'delivery_proof_option_uuid'=>$proof->uuid]);$link->update(['local_shipment_id'=>$shipment->id]);return['status'=>201,'body'=>['data'=>$this->resource($shipment,$link)]];});return$this->idempotentResponse($r,$result);}
 public function show(Request$r,string$shipment){[$link,$item]=$this->owned($r,$shipment);return$this->ok($r,$this->resource($item,$link)+['sender'=>$item->sender_snapshot,'recipient'=>$item->recipient_snapshot,'package'=>$item->package_snapshot]);}
 public function guide(Request$r,string$shipment,LocalGuideService$guides){[, $item]=$this->owned($r,$shipment);return response($guides->pdf($item,parse_url(config('zigo_api_hub.url'),PHP_URL_HOST)),200,['Content-Type'=>'application/pdf','Content-Disposition'=>'inline; filename="'.$item->tracking_number.'.pdf"','X-ZIGO-Request-Id'=>$r->attributes->get('zigo_request_id')]);}
 public function pickup(Request$r,string$shipment,ApiIdempotencyService$idem,LocalTrackingService$tracking){$key=$this->idempotencyKey($r);if(!$key)return$this->error($r,'IDEMPOTENCY_KEY_REQUIRED','Idempotency-Key es obligatorio.',400);[$link,$item]=$this->owned($r,$shipment);$result=$idem->execute($item->tenant_id,$link->api_client_id,'pickups.create',$key,['shipment'=>$item->uuid],function()use($item,$tracking){if($item->status!=='CREATED'&&$item->status!=='READY_FOR_PICKUP')return['status'=>409,'body'=>['error'=>['code'=>'INVALID_SHIPMENT_STATE','message'=>'La recolección no corresponde al estado actual.']]];$tracking->transition($item,'READY_FOR_PICKUP');return['status'=>202,'body'=>['data'=>['shipment_id'=>$item->uuid,'tracking_number'=>$item->tracking_number,'status'=>'READY_FOR_PICKUP']]];});return$this->idempotentResponse($r,$result);}
 private function owned(Request$r,string$uuid):array{$link=TenantApiOperationLink::with('shipment.events')->where('tenant_id',$r->attributes->get('tenant')->id)->where('api_client_id',$r->attributes->get('api_client')->id)->whereHas('shipment',fn($q)=>$q->where('uuid',$uuid))->firstOrFail();return[$link,$link->shipment];}
 private function resource($s,$link):array{return['shipment_id'=>$s->uuid,'tracking_number'=>$s->tracking_number,'status'=>$s->status,'status_label'=>$this->label($s->status),'service'=>$s->service_code,'price_snapshot'=>$s->pricing_snapshot['final_price']??null,'currency'=>$s->pricing_snapshot['currency']??'MXN','external_reference'=>$link->external_reference,'guide_url'=>rtrim(config('zigo_api_hub.url'),'/').'/api/hub/v1/shipments/'.$s->uuid.'/guide','created_at'=>$s->created_at->toIso8601String()];}private function label(string$s):string{return['CREATED'=>'Creado','READY_FOR_PICKUP'=>'Listo para recolectar','PICKED_UP'=>'Recolectado','IN_TRANSIT'=>'En tránsito','OUT_FOR_DELIVERY'=>'En reparto','DELIVERY_FAILED'=>'No entregado','DELIVERED'=>'Entregado','CANCELED'=>'Cancelado'][$s]??'Actualización';}}
